from pathlib import Path
from openhcs.constants.constants import AllComponents
from openhcs.core.config import (
    GlobalPipelineConfig, LazyNapariStreamingConfig, LazyPathPlanningConfig,
    LazyProcessingConfig, LazyStepMaterializationConfig, PipelineConfig,
)
from openhcs.core.source_bindings import (
    ComponentSelector, NamedSourceBinding, SourceBindingsConfig,
    SourceFilterClause, SourceFilterMatchType, SourceFilterSubject, SourceSelector,
)
from openhcs.core.steps.function_step import FunctionStep
from openhcs.processing.backends.processors.numpy_processor import percentile_normalize
from openhcs.processing.backends.analysis.neurite_outgrowth import (
    MetaXpressCellBodySettings, MetaXpressNuclearSettings, MetaXpressOutgrowthSettings,
    neurite_outgrowth_metaxpress,
)

plate_path = Path("/home/ts/code/projects/openhcs/mcp_outputs/website-agent-demo/candidate-20260804-13/plate")
output_root = Path("/home/ts/code/projects/openhcs/mcp_outputs/website-agent-demo/candidate-20260804-13/outputs")

def bind_plane(alias, filename, channel):
    return NamedSourceBinding(
        alias=alias,
        selector=SourceSelector(filters=(SourceFilterClause(
            subject=SourceFilterSubject.FILE,
            match_type=SourceFilterMatchType.EQUALS,
            value=filename,
        ),)),
        component_identity=(
            ComponentSelector(AllComponents.WELL, "1"),
            ComponentSelector(AllComponents.SITE, "1"),
            ComponentSelector(AllComponents.CHANNEL, str(channel)),
            ComponentSelector(AllComponents.Z_INDEX, "1"),
            ComponentSelector(AllComponents.TIMEPOINT, "1"),
        ),
    )

pipeline_config = PipelineConfig(
    materialization_results_path=output_root / "results",
    materialize_runtime_artifacts=True,
    path_planning_config=LazyPathPlanningConfig(
        well_filter=0,
        global_output_folder=output_root,
    ),
    source_bindings_config=SourceBindingsConfig(bindings=(
        bind_plane("W1_neuron_neurite", "1_w1.tif", 1),
        bind_plane("W2_soma_nuclear", "1_w2.tif", 2),
    )),
)

pipeline_steps = [
    FunctionStep(
        name="Enhanced neuronal signal",
        func=(percentile_normalize, dict(
            low_percentile=1.0, high_percentile=99.8,
            target_min=0.0, target_max=255.0,
        )),
        processing_config=LazyProcessingConfig(
            variable_components=(AllComponents.CHANNEL,),
        ),
        step_materialization_config=LazyStepMaterializationConfig(
            enabled=True, global_output_folder=output_root, sub_dir="review_images",
        ),
        napari_streaming_config=LazyNapariStreamingConfig(
            enabled=True, persistent=True, port=5613, colormap="magma",
        ),
    ),
    FunctionStep(
        name="Per-neuron morphology and topology",
        func=(neurite_outgrowth_metaxpress, dict(
            neurite_channel_index=0,
            cell_body=MetaXpressCellBodySettings(
                approximate_max_width=36.0, minimum_area=45.0,
                intensity_above_local_background=20.0, channel_index=0,
            ),
            outgrowth=MetaXpressOutgrowthSettings(
                maximum_width=6.0,
                intensity_above_local_background=8.0,
                minimum_cell_growth_to_log_as_significant=8.0,
            ),
            use_nuclear_stain=True,
            nuclear_stain=MetaXpressNuclearSettings(
                channel_index=1, approx_min_width=5.0, approx_max_width=32.0,
                intensity_above_local_background=18.0,
            ),
        )),
        processing_config=LazyProcessingConfig(
            variable_components=(AllComponents.CHANNEL,),
        ),
        napari_streaming_config=LazyNapariStreamingConfig(
            enabled=True, persistent=True, port=5613, colormap="magma",
        ),
    ),
]

plate_paths = [plate_path]
global_config = GlobalPipelineConfig()
per_plate_configs = {plate_path: pipeline_config}
pipeline_data = {plate_path: pipeline_steps}

